import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 size
)
{
    .reg .u64 %rd<10>;
    .reg .u32 %r<10>;
    .reg .f32 %f<10>;
    .reg .pred %p<3>;

    ld.param.u64 %rd1, [input_ptr];
    ld.param.u64 %rd2, [output_ptr];
    ld.param.u32 %r1, [size];

    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;

    mov.u32 %r6, %nctaid.x;
    mul.lo.s32 %r7, %r6, %r3;

loop:
    setp.ge.s32 %p1, %r5, %r1;
    @%p1 bra done;

    mul.wide.s32 %rd5, %r5, 4;
    add.s64 %rd6, %rd3, %rd5;
    add.s64 %rd7, %rd4, %rd5;

    ld.global.f32 %f1, [%rd6];
    tanh.approx.f32 %f2, %f1;
    st.global.f32 [%rd7], %f2;

    add.s32 %r5, %r5, %r7;
    bra loop;

done:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("tanh_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies Tanh activation to the input tensor using a custom PTX kernel.

        Args:
            x (torch.Tensor): Input tensor of any shape (must be float32, CUDA).

        Returns:
            torch.Tensor: Output tensor with Tanh applied, same shape as input.
        """
        assert x.is_cuda, "Input tensor must be on CUDA device"
        assert x.dtype == torch.float32, "Input tensor must be float32"

        x_contig = x.contiguous()
        output = torch.empty_like(x_contig)

        size = x_contig.numel()

        block_x = 256
        grid_x = (size + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "tanh_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x_contig, output, i32(size)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output.view(x.shape)

